	onStrike() {
		let tmp = this.game;
		let blist = tmp != null ? tmp.getList(Data.BAD_CLEAR) : null;
		if((blist != null ? blist.length : null) == 0 || blist == null) {
			return;
		}
		let bad;
		let n = 0;
		do {
			bad = blist[n];
			n += 1;
		} while((bad != null ? bad.fl_kill : null) == true);
		if((bad != null ? bad.fl_kill : null) == false) {
			let tmp = this.game;
			let tmp1 = tmp != null ? tmp.depthMan : null;
			let s = tmp1 != null ? tmp1.attach("hammer_fx_strike",Data.FX) : null;
			if(s != null) {
				s._x = Data.DOC_WIDTH / 2;
			}
			if(s != null) {
				s._y = (bad != null ? bad.get__y() : null) - Data.CASE_HEIGHT * 0.5;
			}
			let dir = mtlib_MtStd.random(2) * 2 - 1;
			if(s != null) {
				s._xscale *= dir;
			}
			if(s != null) {
				s._yscale = mtlib_MtStd.random(50) + 50;
			}
			let tmp2 = this.game;
			let tmp3 = tmp2 != null ? tmp2.fxMan : null;
			if(tmp3 != null) {
				tmp3.attachShine(bad != null ? bad.x : null,bad != null ? bad.y : null);
			}
			if(bad != null) {
				bad.forceKill(dir * (mtlib_MtStd.random(10) + 15));
			}
		}
	}
	onFireRain() {
		let x = mtlib_MtStd.random(Math.round(Data.GAME_WIDTH)) + 50;
		let s = entity_shoot_FireRain.attach(this.game,x,-mtlib_MtStd.random(50));
		if(s != null) {
			s.moveToAng(95 + mtlib_MtStd.random(30),s != null ? s.shootSpeed : null);
		}
	}
	onPoT() {
		let tmp = this.player;
		if(tmp != null) {
			tmp.getScore(this.player,250);
		}
	}
	main() {
		let n = 0;
		while(true) {
			let tmp = this.recurring;
			if(!(n < (tmp != null ? tmp.length : null))) {
				break;
			}
			let e = this.recurring[n];
			if(e != null) {
				e.timer -= mtlib_Timer.tmod;
			}
			if((e != null ? e.timer : null) <= 0) {
				if(e != null) {
					e.func();
				}
				if(e != null ? e.fl_repeat : null) {
					if(e != null) {
						e.timer = (e != null ? e.baseTimer : null) + (e != null ? e.timer : null);
					}
				} else {
					let tmp = this.recurring;
					if(tmp != null) {
						tmp.splice(n,1);
					}
					n -= 1;
				}
			}
			n += 1;
		}
		let tmp = this.phoneMC;
		if((tmp != null ? tmp._name : null) != null) {
			let d = new Date();
			let str = "" + Std.string(d != null ? d.getHours() : null);
			if((str != null ? str.length : null) < 2) {
				str = "0" + Std.string(str);
			}
			str = Std.string(str) + ":";
			if((d != null ? d.getMinutes() : null) < 10) {
				str = Std.string(str) + "0" + Std.string(d != null ? d.getMinutes() : null);
			} else {
				str += d != null ? d.getMinutes() : null;
			}
			let tmp = this.phoneMC;
			let tmp1 = tmp != null ? tmp.screen : null;
			if((tmp1 != null ? tmp1.field : null) != null) {
				this.phoneMC.screen.field.text = str;
			}
		}
		let i = 0;
		while(true) {
			let tmp = this.tempList;
			if(!(i < (tmp != null ? tmp.length : null))) {
				break;
			}
			let tmp1 = this.game;
			let tmp2 = this.tempList[i];
			if((tmp1 != null ? tmp1.cycle : null) >= (tmp2 != null ? tmp2.end : null)) {
				let tmp = this.tempList[i];
				this.interrupt(tmp != null ? tmp.id : null);
				let tmp1 = this.tempList;
				if(tmp1 != null) {
					tmp1.splice(i,1);
				}
				i -= 1;
			}
			i += 1;
		}
	}
