	runScript() {
		if(this.script == null) {
			return;
		}
		let tmp = this.script;
		let trigger = tmp != null ? tmp.firstChild : null;
		while(trigger != null) {
			if(this.checkTrigger(trigger)) {
				let kid = this.getInt(trigger,"$key");
				let tmp = this.game;
				if(!(tmp != null ? tmp.hasKey(kid) : null)) {
					if(this.isVerbose(trigger != null ? trigger.nodeName : null)) {
						let tmp = this.game;
						let tmp1 = tmp != null ? tmp.fxMan : null;
						if(tmp1 != null) {
							tmp1.keyRequired(kid);
						}
					}
				} else {
					if(kid != null) {
						let tmp = this.game;
						let tmp1 = tmp != null ? tmp.fxMan : null;
						if(tmp1 != null) {
							tmp1.keyUsed(kid);
						}
					}
					this.executeTrigger(trigger);
				}
			}
			trigger = trigger != null ? trigger.nextSibling : null;
		}
		this.fl_birth = false;
		this.fl_death = false;
		this.fl_onAttach = false;
		this.recentExp = [];
		this.entries = [];
		this.fl_onAttach = false;
	}
	compile() {
		this.history = [];
		this.traceHistory(this.baseScript);
		let node = new mtlib_MtXml(this.baseScript).firstChild;
		while(node != null) {
			if((node != null ? node.nodeName : null) != null) {
				this.traceHistory("b " + Std.string(node != null ? node.nodeName : null));
			}
			node = node != null ? node.nextSibling : null;
		}
		node = new mtlib_MtXml(this.extraScript).firstChild;
		while(node != null) {
			if((node != null ? node.nodeName : null) != null) {
				this.traceHistory("b2 " + Std.string(node != null ? node.nodeName : null));
			}
			node = node != null ? node.nextSibling : null;
		}
		let doc = new mtlib_MtXml(this.baseScript + " " + this.extraScript);
		if(doc != null) {
			doc.ignoreWhite = true;
		}
		if(doc == null) {
			GameManager.fatal("compile: invalid XML");
		} else {
			this.script = doc;
		}
		this.normalMode();
		this.fl_compile = true;
		this.traceHistory("first=" + this.cycle);
		this.runScript();
	}
	clearScript() {
		this.script = null;
		this.baseScript = "";
		this.extraScript = "";
		this.cycle = 0;
		this.fl_compile = false;
	}
	clearEndTriggers() {
		let tmp = this.script;
		let trigger = tmp != null ? tmp.firstChild : null;
		while(trigger != null) {
			let next = trigger != null ? trigger.nextSibling : null;
			if((trigger != null ? trigger.get("$endClear") : null) == "1") {
				this.traceHistory("eX " + (trigger != null ? trigger.nodeName : null));
				if(trigger != null) {
					trigger.removeNode();
				}
			}
			trigger = next;
		}
	}
