	getClose(type,x,y,radius,fl_onGround) {
		let l = this.getList(type);
		let out = [];
		let sqrRad = Math.pow(radius,2);
		let i = 0;
		while(i < (l != null ? l.length : null)) {
			let e = l[i];
			let square = Math.pow((e != null ? e.x : null) - x,2) + Math.pow((e != null ? e.y : null) - y,2);
			if(square <= sqrRad) {
				if(Math.sqrt(square) <= radius) {
					if(!fl_onGround || fl_onGround && (e != null ? e.y : null) <= y + Data.CASE_HEIGHT) {
						if(out != null) {
							out.push(e);
						}
					}
				}
			}
			i += 1;
		}
		return out;
	}
